import itertools
from pysat.solvers import Glucose3
from pysat.card import CardEnc

def solve():
    n = 11
    fixed_edges = [(5, 6), (3, 8), (0, 9), (3, 7), (3, 9), (4, 9)]

    all_possible_edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if (u, v) not in fixed_edges:
                all_possible_edges.append((u, v))

    degrees = [0] * n
    for u, v in fixed_edges:
        degrees[u] += 1
        degrees[v] += 1

    if any(d > 6 for d in degrees):
        return None

    solver = Glucose3()

    edge_to_id = {}
    id_to_edge = {}
    for i, edge in enumerate(all_possible_edges):
        edge_to_id[edge] = i + 1
        id_to_edge[i + 1] = edge

    for v in range(n):
        d_v = degrees[v]
        edges_v = []
        for u in range(n):
            if u == v: continue
            edge = tuple(sorted((u, v)))
            if edge in fixed_edges: continue
            edges_v.append(edge_to_id[edge])

        # sum(edges_v) >= 4 - d_v
        # sum(edges_v) <= 6 - d_v

        min_needed = max(0, 4 - d_v)
        max_needed = 6 - d_v

        if max_needed < 0:
            return None

        # Add cardinality constraints
        # At least min_needed
        if min_needed > 0:
            clauses = CardEnc.atleast(lits=edges_v, bound=min_needed).clauses
            for c in clauses:
                solver.add_clause(c)

        # At most max_needed
        if max_needed < len(edges_v):
            clauses = CardEnc.atmost(lits=edges_v, bound=max_needed).clauses
            for c in clauses:
                solver.add_clause(c)

    if solver.solve():
        model = solver.get_model()
        result_edges = list(fixed_edges)
        for i in range(1, len(all_possible_edges) + 1):
            if model[i-1] > 0:
                result_edges.append(id_to_edge[i])
        return result_edges
    else:
        return None

result = solve()
print(result)
